/bin/bash -lc "awk -F '\\t' '
NR==1 {fields=NF; next}
NF"'!=fields {print "FIELD_COUNT_ERROR line=" NR " expected=" fields " got=" NF; bad=1}
seen_entry[$1]++ {print "DUPLICATE_ENTRY " $1; bad=1}
seen_sense[$2]++ {print "DUPLICATE_SENSE " $2; bad=1}
$1=="E1" && !($13=="U10" && $14=="C1:10") {print "BAD_E1_LINK"; bad=1}
$1=="E2" && !($13=="U11" && $14=="C1:11") {print "BAD_E2_LINK"; bad=1}
$1=="E3" && !($13=="U12" && $14=="C1:12") {print "BAD_E3_LINK"; bad=1}
$1=="E4" && !($13=="U99" && $14=="unresolved reference: no C1 anchor") {print "BAD_E4_LINK"; bad=1}
END {if (NR!=5) {print "ROW_COUNT_ERROR records=" NR-1; bad=1}; if (!bad) print "TSV_OK fields=" fields " records=" NR-1 " unique_entry_ids=" length(seen_entry) " unique_sense_ids=" length(seen_sense); exit bad}
'"' outputs/lexicon.tsv
rg -n '"'^# (Curation Context|Lexicon Or Corpus Index|Attestation Links|Merge And Variant Decisions|Unresolved Analyses|Checks And Limits|Owner Questions|Files Changed|Handoffs)$'"' outputs/curation-decisions.md
rg -n 'E[1-4]-S1|U(10|11|12|99)|A12|P1|X1' outputs/lexicon.tsv outputs/curation-decisions.md"
